        <a class="btn btn-primary" href="eshop_orders_admin.php">Vybrat objednávku</a>
    </main></body></html>
    <?php
    exit;
}
$orderId=(int)($_GET['order_id']??$_POST['order_id']??0);$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if(!csrf_verify((string)($_POST['csrf_token']??'')))throw new InvalidArgumentException('Formulář vypršel.');if(($_POST['confirmed']??'')!=='1')throw new InvalidArgumentException('Potvrďte skutečné předání nebo ověřený stav zásilky.');
  $actor=(int)$_SESSION['trener_id'];$recipient=(string)($_POST['recipient']??'');$date=str_replace('T',' ',(string)($_POST['occurred_at']??''));if(strlen($date)===16)$date.=':00';$reason=(string)($_POST['reason']??'');$key=(string)($_POST['request_key']??'');
  if(($_POST['action']??'')==='issue')$result=shopFulfillmentIssue($pdo,$orderId,(array)($_POST['quantity']??[]),$actor,$recipient,$date,$reason,$key);
  elseif(($_POST['action']??'')==='release')$result=shopFulfillmentReleaseRemainder($pdo,$orderId,(int)($_POST['order_item_id']??0),(int)($_POST['correction_id']??0),$actor,$reason,$key);
  elseif(($_POST['action']??'')==='delivery')$result=shopFulfillmentDeliveryRecord($pdo,$orderId,(string)($_POST['delivery_status']??''),$actor,$recipient,$date,$reason,$key);
  else throw new InvalidArgumentException('Neznámá operace.');
  $_SESSION['fulfillment_message']=$result['changed']?'Záznam je uložen. Peněžní vratka a návrat zboží na sklad se řeší samostatně.':'Tento úkon už byl zaznamenán; nevznikla další změna.';
  header('Location: eshop_fulfillment_admin.php?order_id='.$orderId,true,303);exit;
 }catch(Throwable $e){$error=$e instanceof PDOException?'Databázová operace selhala bez částečného zápisu.':$e->getMessage();}
}
$message=(string)($_SESSION['fulfillment_message']??'');unset($_SESSION['fulfillment_message']);
$s=$pdo->prepare('SELECT * FROM shop_orders WHERE id=?');$s->execute([$orderId]);$order=$s->fetch(PDO::FETCH_ASSOC);
if(!$order){http_response_code(404);exit('Objednávka nebyla nalezena.');}
$s=$pdo->prepare('SELECT oi.*,p.offer_type FROM shop_order_items oi JOIN shop_products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$s->execute([$orderId]);$items=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare('SELECT f.*,i.order_item_id,i.variant_id,i.quantity,i.inventory_movement_id,oi.sku_snapshot FROM shop_fulfillments f JOIN shop_fulfillment_items i ON i.fulfillment_id=f.id JOIN shop_order_items oi ON oi.id=i.order_item_id WHERE f.order_id=? ORDER BY f.id,i.id');$s->execute([$orderId]);$history=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare('SELECT * FROM shop_delivery_events WHERE order_id=? ORDER BY id');$s->execute([$orderId]);$delivery=$s->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare("SELECT * FROM shop_stock_movements WHERE order_id=? AND kind='release' ORDER BY id");$s->execute([$orderId]);$released=$s->fetchAll(PDO::FETCH_ASSOC);
$resolution=shopFulfillmentResolution($pdo,$orderId);$resolutionLabel=shopFulfillmentResolutionLabel($resolution);
$carrier=in_array($order['fulfillment_method'],['ppl_box','packeta_zbox'],true);
?>
