<?php foreach([$error=>'danger',$message=>'success'] as $text=>$style):if($text!==''):?><div class="alert alert-<?=$style?>"><?=fulfillmentH($text)?></div><?php endif;endforeach;?>
<?php if($carrier):?><div class="alert alert-info">Výdej celé zásilky zaznamenejte v objednávce při fyzickém předání dopravci. Předání dopravci není potvrzení doručení zákazníkovi. Ztráta ani nevyzvednutí automaticky nevrátí zboží na sklad.</div><?php endif;?>
<form method="post" class="card card-body"><?=csrf_field()?><input type="hidden" name="action" value="issue"><input type="hidden" name="order_id" value="<?=$orderId?>"><input type="hidden" name="request_key" value="<?=fulfillmentH($_POST['request_key']??bin2hex(random_bytes(16)))?>"><h2 class="h5">Položky a zbývající rezervace</h2><table class="table"><thead><tr><th>Položka</th><th>Objednáno</th><th>Vydáno</th><th>Zbývá</th><th>Nevydáno / uvolněno</th><th>Předat nyní</th></tr></thead><tbody>
<?php foreach($items as $item):$managed=$item['offer_type']==='goods'&&shopInventoryManaged($pdo,(int)$item['variant_id']);$r=$managed?shopInventoryReservation($pdo,(int)$item['id']):null;?><tr><td><?=fulfillmentH($item['product_name_snapshot'].' · '.$item['sku_snapshot'])?><?php if(!$managed):?><div class="text-muted"><?=$item['offer_type']==='goods'?'Neověřený původní sklad; nutný převod':'Služba – bez skladového výdeje'?></div><?php endif;?></td><td><?=(int)$item['quantity']?></td><td><?=$r?(int)$r['issued_quantity']:'—'?></td><td><?=$r?(int)$r['remaining_quantity']:'—'?></td><td><?=$r?(int)$r['released_quantity']:'—'?></td><td><?php if(!$carrier&&$r&&(int)$r['remaining_quantity']>0&&$order['payment_status']==='paid'&&in_array($order['status'],['processing','ready'],true)):?><input class="form-control" type="number" min="0" max="<?=(int)$r['remaining_quantity']?>" name="quantity[<?=(int)$item['id']?>]" value="0"><?php endif;?></td></tr><?php endforeach;?></tbody></table>
<?php if(!$carrier&&$order['payment_status']==='paid'&&in_array($order['status'],['processing','ready'],true)):?><label>Přebírající<input class="form-control" name="recipient" maxlength="200" required value="<?=fulfillmentH($_POST['recipient']??$order['customer_name_snapshot'])?>"></label><label>Skutečný čas<input class="form-control" type="datetime-local" name="occurred_at" required value="<?=date('Y-m-d\TH:i')?>"></label><label>Poznámka / důkaz předání<input class="form-control" name="reason" maxlength="1000" required></label><label><input type="checkbox" name="confirmed" value="1" required> Uvedené kusy byly skutečně předány.</label><button class="btn btn-primary mt-2">Zapsat položkový výdej</button><?php endif;?></form>
<?php if($order['payment_status']==='paid'&&in_array($order['status'],['processing','ready'],true)):?><details class="card card-body mt-3"><summary>Vypořádat nevydaný zbytek podle opravného dokladu</summary><p>Hospodář nejprve vystaví opravný doklad s množstvím zrušených kusů. Tento krok uvolní rezervaci, fyzické kusy zůstávají ve skladu. Peníze musí hospodář vrátit samostatně.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="release"><input type="hidden" name="order_id" value="<?=$orderId?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>"><label>Položka<select class="form-select" name="order_item_id" required><?php foreach($items as $item):if($item['offer_type']!=='goods'||!shopInventoryManaged($pdo,(int)$item['variant_id']))continue;$r=shopInventoryReservation($pdo,(int)$item['id']);if(!$r||(int)$r['remaining_quantity']<1)continue;?><option value="<?=(int)$item['id']?>"><?=fulfillmentH($item['sku_snapshot'])?> · nevydáno <?=(int)$r['remaining_quantity']?> ks</option><?php endforeach;?></select></label><label>ID vydaného opravného dokladu<input class="form-control" name="correction_id" type="number" min="1" required></label><label>Důvod<input class="form-control" name="reason" maxlength="1000" required></label><label><input type="checkbox" name="confirmed" value="1" required> Zbytek nebyl předán a oprava odpovídá zrušeným kusům.</label><button class="btn btn-outline-danger mt-2">Uvolnit doložený nevydaný zbytek</button></form></details><?php endif;?>
<?php if($carrier&&(!empty($order['ppl_dispatched_at'])||!empty($order['packeta_deposited_at']))):?><form method="post" class="card card-body mt-3"><?=csrf_field()?><input type="hidden" name="action" value="delivery"><input type="hidden" name="order_id" value="<?=$orderId?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>"><h2 class="h5">Ověřený výsledek doručení</h2><select class="form-select" name="delivery_status"><option value="delivered">Převzato zákazníkem</option><option value="undelivered">Nedoručeno / nevyzvednuto</option><option value="lost">Ztraceno</option><option value="damaged">Poškozeno</option></select><label>Příjemce nebo ověřený kontakt<input class="form-control" name="recipient" maxlength="200" required></label><label>Skutečný čas<input class="form-control" type="datetime-local" name="occurred_at" value="<?=date('Y-m-d\TH:i')?>" required></label><label>Zdroj ověření a další postup<input class="form-control" name="reason" maxlength="1000" required></label><label><input type="checkbox" name="confirmed" value="1" required> Stav jsem ověřil/a. Tento záznam nepřijímá zboží zpět na sklad.</label><button class="btn btn-outline-primary mt-2">Zaznamenat výsledek</button></form><?php endif;?>
<h2 class="h4 mt-4">Předávací podklad</h2><table class="table"><thead><tr><th>Výdej</th><th>Čas</th><th>SKU / kusy</th><th>Přebírající</th><th>Pracovník</th><th>Poznámka</th></tr></thead><tbody><?php foreach($history as $line):?><tr><td>#<?=(int)$line['id']?> · <?=fulfillmentH($line['channel'])?><br><a class="no-print" href="shop_stock_document.php?id=<?=(int)$line['inventory_movement_id']?>">Archivovaná výdejka PDF</a></td><td><?=fulfillmentH($line['occurred_at'])?></td><td><?=fulfillmentH($line['sku_snapshot'])?> × <?=(int)$line['quantity']?></td><td><?=fulfillmentH($line['recipient'])?></td><td>#<?=(int)$line['actor_trainer_id']?></td><td><?=fulfillmentH($line['reason'])?></td></tr><?php endforeach;?></tbody></table><h2 class="h5">Uvolněné nevydané kusy</h2><?php foreach($released as $line):$meta=json_decode($line['meta_json'],true);?><p><?=fulfillmentH($line['recorded_at'].' · '.(-(int)$line['reserved_delta']).' ks · '.$line['reason'])?><?php if(isset($meta['correction_document_id'])):?> · opravný doklad #<?=(int)$meta['correction_document_id']?><?php endif;?></p><?php endforeach;?><h2 class="h5">Historie doručení</h2><?php foreach($delivery as $line):?><p><?=fulfillmentH($line['occurred_at'].' · '.$line['status'].' · '.$line['recipient'].' · '.$line['reason'])?></p><?php endforeach;?></main><script nonce="<?=fulfillmentH(app_csp_nonce())?>">document.getElementById("print-handoff").addEventListener("click",function(){window.print();});</script></body></html>
